#include <stdio.h>
#include <stddef.h>

struct assoc_desc {
	unsigned char bFirstInterface;
};

struct config {
	struct assoc_desc *intf_assoc[8];
};

struct udev {
	struct config *actconfig;
};

static int guard(struct udev *udev, int ifnum, int *dereferenced)
{
	struct assoc_desc *assoc_desc = udev->actconfig->intf_assoc[0];

	if (!assoc_desc || assoc_desc->bFirstInterface != ifnum) {
		/* error path: must not have dereferenced a NULL pointer */
		return -19; /* -ENODEV */
	}
	*dereferenced = 1;
	return 0;
}

int main(void)
{
	int deref = 0;
	int failures = 0;

	/* Positive path: IAD present and matches -> probe continues */
	{
		struct assoc_desc iad = { .bFirstInterface = 1 };
		struct config cfg = { .intf_assoc = { &iad } };
		struct udev udev = { .actconfig = &cfg };
		deref = 0;
		int r = guard(&udev, 1, &deref);
		printf("positive(match):      ret=%d deref=%d\n", r, deref);
		if (r != 0 || deref != 1) { printf("FAIL positive\n"); failures++; }
	}

	/* Positive path: IAD present but interface mismatch -> -ENODEV */
	{
		struct assoc_desc iad = { .bFirstInterface = 5 };
		struct config cfg = { .intf_assoc = { &iad } };
		struct udev udev = { .actconfig = &cfg };
		deref = 0;
		int r = guard(&udev, 1, &deref);
		printf("positive(mismatch):   ret=%d deref=%d\n", r, deref);
		if (r != -19 || deref != 0) { printf("FAIL mismatch\n"); failures++; }
	}

	/* Negative/vulnerability path: IAD missing (NULL) -> must short-circuit */
	{
		struct config cfg = { .intf_assoc = { NULL } };
		struct udev udev = { .actconfig = &cfg };
		deref = 0;
		int r = guard(&udev, 1, &deref);
		printf("negative(NULL IAD):   ret=%d deref=%d\n", r, deref);
		if (r != -19 || deref != 0) { printf("FAIL null guard\n"); failures++; }
	}

	if (failures) {
		printf("RESULT: FAIL (%d)\n", failures);
		return 1;
	}
	printf("RESULT: PASS (guard short-circuits on NULL, preserves behavior)\n");
	return 0;
}

